// O agente responde TEXTO; aqui vira { output: { reply, handoff } } sempre.
// handoff = a marca [SUPORTE] (ou [HANDOFF]) no texto, que e removida da resposta.
// Se o modelo mesmo assim devolver JSON {reply, handoff}, tambem e aceito.
const MARCA = /\[\s*(SUPORTE|HANDOFF)\s*\]/gi;

// O gpt-oss-120b as vezes despeja entulho antes da resposta (exec 263: 207 tokens
// de saida para 60 caracteres uteis). Isto descarta enfeite, nunca reescreve texto.
function limpar(s) {
  let t = String(s ?? '').replace(/[   ​]/g, ' ');

  // 3+ quebras seguidas nao aparecem em resposta legitima: separa entulho da resposta
  const blocos = t.split(/\n{3,}/).map((b) => b.trim()).filter(Boolean);
  if (blocos.length > 1) t = blocos[blocos.length - 1];

  // O modelo as vezes despeja o raciocinio (em ingles) colado na resposta.
  // Assinatura: frases de meta-comentario. O corte e no ultimo ponto/dois-pontos
  // GRUDADO numa maiuscula — pontuacao sem espaco depois nao acontece em texto normal.
  const RACIOCINIO = /\b(the assistant|should respond|need to|keep short|garbled|nonsense|one emoji|we (?:need|should)|user (?:is|wants|asked)|let'?s |i should)\b/i;
  if (RACIOCINIO.test(t)) {
    const grudado = [...t.matchAll(/[.!?:](?=[A-ZÀ-Ý])/g)];
    if (grudado.length) {
      t = t.slice(grudado[grudado.length - 1].index + 1);
    } else {
      // separado por espaco: descarta as frases iniciais que sao meta-comentario
      const frases = t.split(/(?<=[.!?])\s+/);
      let i = 0;
      while (i < frases.length - 1 && RACIOCINIO.test(frases[i])) i++;
      if (i > 0) t = frases.slice(i).join(' ');
    }
  }

  return t
    .replace(/^[\s.*_~\-=…·•]{3,}/, '')
    .replace(/…{2,}|\.{4,}|\*{2,}|_{3,}|~{3,}/g, '')
    .replace(/\n{3,}/g, '\n\n')
    .replace(/[ \t]{2,}/g, ' ')
    .replace(/[ \t]+([.,!?])/g, '$1')
    .trim();
}
return $input.all().map((item) => {
  if (item.json.output === undefined) {
    // sem `output` = o no do agente nao produziu resposta (falhou e seguiu com onError=continue)
    // o no do agente falhou (modelo/Groq fora, 400, etc.): nao deixa o usuario sem resposta
    return { json: { output: { reply: 'Tive um problema pra responder agora. Um atendente já vai falar com você por aqui.', handoff: true, resumo: null }, erroAgente: String(item.json.error?.message || item.json.error || 'agente sem output').slice(0, 300) } };
  }
  const raw = item.json.output;
  let reply = null, handoff = false;
  if (raw && typeof raw === 'object' && typeof raw.reply === 'string') {
    reply = raw.reply; handoff = raw.handoff === true;
  } else {
    let s = String(raw ?? '').trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
    const i = s.indexOf('{'), j = s.lastIndexOf('}');
    if (i === 0 && j > i) {
      try { const o = JSON.parse(s.slice(i, j + 1)); if (o && typeof o.reply === 'string') { reply = o.reply; handoff = o.handoff === true; } } catch (e) { /* nao era JSON */ }
    }
    if (reply === null) reply = s;
  }
  // Triagem: a ultima linha "RESUMO: pedido X · motivo" vai pro painel (handoffMotivo), nao pro contato.
  // Extraida ANTES do limpar(): ele descarta blocos separados por 3+ quebras.
  let resumo = null;
  const mRes = reply.match(/^[ \t]*RESUMO\s*:\s*(.+?)\s*$/im);
  if (mRes) { resumo = mRes[1].replace(MARCA, '').trim().slice(0, 300) || null; reply = reply.replace(mRes[0], ''); }
  if (MARCA.test(reply)) { handoff = true; }
  reply = limpar(reply.replace(MARCA, '')).replace(/[ 	]{2,}/g, ' ').replace(/[ 	]+([.,!?])/g, '$1').trim();
  if (!reply) { reply = 'Não consegui responder agora. Um atendente já vai falar com você por aqui.'; handoff = true; }
  return { json: { output: { reply, handoff, resumo } } };
});

// Lê o identificar e monta os blocos que entram no prompt dos agentes. Sem rótulo quando vazio:
// cada linha aqui custa token na Groq (8k/min compartilhados pelas duas IAs).
const id = $('Identificar').first().json || {};
const limpa = (s) => String(s ?? '').replace(/\s+/g, ' ').trim();

let blocoPendentes = '';
if (Array.isArray(id.pendentes) && id.pendentes.length) {
  blocoPendentes = 'ELE MANDOU ANTES E NINGUÉM RESPONDEU (responda junto com a atual, uma frase cada, tudo numa resposta só):\n' +
    id.pendentes.slice(0, 3).map((p) => '- ' + limpa(p.texto).slice(0, 160)).join('\n');
}

let blocoCorridas = '';
if (id.perfil === 'motoboy') {
  if (!Array.isArray(id.corridas)) blocoCorridas = 'PEDIDOS EM ABERTO COM ELE AGORA: não consegui consultar agora (se ele perguntar, use "Minhas corridas").';
  else if (!id.corridas.length) blocoCorridas = 'PEDIDOS EM ABERTO COM ELE AGORA: nenhum.';
  else blocoCorridas = 'PEDIDOS EM ABERTO COM ELE AGORA: ' + id.corridas.slice(0, 5).map((c) => '#' + c.codigo + (c.loja ? ' ' + limpa(c.loja) : '') + (c.etapa ? ' (' + c.etapa + ')' : '')).join('; ') + '.';
}

const retiradaLigada = id.retiradaPelaIA === true;
const blocoRetirada = retiradaLigada
  ? "TIRAR PEDIDO DA TELA (você pode, pela ferramenta \"Retirar pedido\"). Quando ele quer largar, tirar ou trocar um pedido dele:\n(1) se há mais de um pedido em aberto e ele não disse qual, pergunte qual pelo número;\n(2) se ainda não disse o motivo, pergunte em uma frase;\n(3) chame \"Retirar pedido\" com o código e o motivo. feito → \"Pronto, tirei o pedido #<código> da sua tela. A equipe foi avisada.\" ja_coletada → não dá depois da coleta: diga isso, termine com [SUPORTE] e a última linha RESUMO: pedido <n> · <motivo>. de_outro_entregador → esse pedido não está no nome dele. nao_encontrado → peça o número de novo. desligado, banco_indisponivel ou nao_alterou → diga que um atendente vai cuidar por aqui, termine com [SUPORTE] e a última linha RESUMO: pedido <n> · <motivo>."
  : "TIRAR PEDIDO DA TELA (hoje é a equipe que faz; a ferramenta \"Retirar pedido\" está DESLIGADA, não chame). Quando ele quer largar, tirar, trocar ou cancelar um pedido dele:\n(1) se há mais de um pedido em aberto e ele não disse qual, pergunte qual pelo número;\n(2) pergunte em uma frase o que aconteceu (o motivo);\n(3) com pedido e motivo, diga que um atendente vai cuidar disso por aqui, termine com [SUPORTE] e, na ÚLTIMA linha, escreva exatamente: RESUMO: pedido <número> · <o que aconteceu>.\nSe ele já disse pedido e motivo na própria mensagem, vá direto ao (3). Uma pergunta por vez.";
const blocoFila = id.aguardandoHumano === true ? "ESTA CONVERSA JÁ ESTÁ COM A EQUIPE (um atendente foi chamado e ainda não respondeu). Se ele cobrar, diga que a equipe já foi avisada e vai falar por aqui. Não termine com [SUPORTE] de novo. O resto, responda normalmente." : '';

return [{ json: { modoRetirada: retiradaLigada ? 'ligada' : 'triagem', blocoPendentes, blocoCorridas, blocoRetirada, blocoFila } }];
